"""Graph creation utilities for flat-folder."""

import math
from bp_pipeline import timeout as timeout_lib
from . import logging
from . import math_utils
from . import sorted_list

Point = math_utils.Point
Line = math_utils.Line
Edge = math_utils.Edge

_TARGET_STABILITY = 3
_EXPONENT_OFFSET = 3
_MAX_ITERATIONS = 50


def _compare_points(point1: Point, point2: Point, epsilon: float) -> int:
  """Compares two points lexicographically using epsilon tolerance.

  Args:
    point1: The first point [x1, y1].
    point2: The second point [x2, y2].
    epsilon: Tolerance for floating-point comparisons.

  Returns:
    -1 if point1 < point2, 1 if point1 > point2, 0 if point1 == point2
    within tolerance.
  """
  x1, y1 = point1
  x2, y2 = point2
  if not math.isclose(y1, y2, abs_tol=epsilon):
    return -1 if y1 < y2 else 1
  if not math.isclose(x1, x2, abs_tol=epsilon):
    return -1 if x1 < x2 else 1
  return 0


def _line_intersect(
    point1: Point, point2: Point, point3: Point, point4: Point, epsilon: float
) -> Point | None:
  """Computes intersection of two lines point1-point2 and point3-point4.

  Args:
    point1: The first point of the first line.
    point2: The second point of the first line.
    point3: The first point of the second line.
    point4: The second point of the second line.
    epsilon: Tolerance for floating-point comparisons.

  Returns:
    The intersection point [x, y] if lines intersect, otherwise None.
  """
  x1, y1 = point1
  x2, y2 = point2
  x3, y3 = point3
  x4, y4 = point4
  dx12 = x1 - x2
  dy12 = y1 - y2
  dx34 = x3 - x4
  dy34 = y3 - y4
  denom = dx12 * dy34 - dx34 * dy12
  if abs(denom) < epsilon**2:
    return None
  x = ((x1 * y2 - y1 * x2) * dx34 - (x3 * y4 - y3 * x4) * dx12) / denom
  y = ((x1 * y2 - y1 * x2) * dy34 - (x3 * y4 - y3 * x4) * dy12) / denom
  return (x, y)


def create_graph_from_lines(
    lines: list[Line],
) -> tuple[list[Point], list[Edge], list[list[int]], int]:
  """Computes graph representation from lines, choosing epsilon for stability.

  It iteratively reduces epsilon, looking for a stable number of vertices
  and edges in graph generated by _create_graph_from_lines_eps.

  Args:
      lines: A list of lines, where each line is a tuple of two points.

  Returns:
      A tuple containing:
      - vertices: List of vertex coordinates.
      - edge_vertices: List of edges defined by vertex indices.
      - edge_lines: List mapping edges to original line indices.
      - stability_offset: An integer offset related to stability calculation.
  """
  min_line_length = math_utils.min_line_length(lines)
  if min_line_length == 0:
    min_line_length = 1.0

  vertex_count, edge_count, stability_count = 0, 0, 0
  result_vertices: list[Point] = []
  result_edge_vertices: list[Edge] = []
  result_edge_lines: list[list[int]] = []
  max_stability, best_exponent = 1, 1

  logging.NOTE.start_check("epsilon")
  for exponent_i in range(_MAX_ITERATIONS):
    timeout_lib.maybe_timeout_cooperatively()
    exponent = exponent_i + _EXPONENT_OFFSET
    epsilon = min_line_length / (2**exponent)
    logging.NOTE.check(2**exponent)
    if epsilon < math_utils.FLOAT_EPSILON:
      break
    try:
      new_vertices, new_edge_vertices, new_edge_lines = (
          _create_graph_from_lines_eps(lines, epsilon)
      )
      if (
          len(new_vertices) == vertex_count
          and len(new_edge_vertices) == edge_count
      ):
        stability_count += 1
      else:
        vertex_count = len(new_vertices)
        edge_count = len(new_edge_vertices)
        stability_count = 1

      if stability_count >= max_stability:
        result_vertices, result_edge_vertices, result_edge_lines = (
            new_vertices,
            new_edge_vertices,
            new_edge_lines,
        )
        max_stability, best_exponent = stability_count, exponent

      if stability_count == _TARGET_STABILITY:
        break
    except (ValueError, IndexError):
      logging.NOTE.log(
          f"Warning: Graph construction failed at eps={epsilon:.2e}"
      )
      vertex_count, edge_count, stability_count = 0, 0, 0

  return (
      result_vertices,
      result_edge_vertices,
      result_edge_lines,
      best_exponent - max_stability,
  )


class _SweepLineRunner:
  """Runs the sweep-line algorithm to build a graph from line segments."""

  def __init__(self, lines: list[Line], epsilon: float):
    """Initializes the sweep-line runner.

    Args:
        lines: A list of lines, where each line is a tuple of two points.
        epsilon: Tolerance for floating-point comparisons.
    """
    self.lines = lines
    self.epsilon = epsilon
    self.vertices: list[Point] = [(float("-inf"), float("-inf"))]
    self.vertex_lines: list[list[int]] = [[]]
    self.line_vertices: list[Edge] = []
    self.line_unit_vectors: list[Point] = []
    self.line_angles: list[float] = []
    self.line_distances: list[float] = []
    self.vertex_queue = sorted_list.SortedList(self._compare_vertex_indices)
    self.segment_endpoints: list[list[int | None]] = [[None, None]]
    self.segment_unit_vectors: list[Point] = [(-1, 0)]
    self.segment_angles: list[float] = [float("inf")]
    self.segment_distances: list[float | None] = [None]
    self.segment_lines: list[list[int]] = [[]]
    self.current_vertex_index_for_sweep: int = 0
    self.sweep_line = sorted_list.SortedList(self._compare_segments)
    self.vertex_to_intersection_point_map: list[int | None] = []
    self.intersection_points: list[Point] = []

  def _compare_vertex_indices(self, i1: int, i2: int) -> int:
    """Compares vertex indices based on vertex coordinates.

    Args:
      i1: Index of the first vertex.
      i2: Index of the second vertex.

    Returns:
      -1, 0, or 1 based on lexicographical comparison of vertices.
    """
    return _compare_points(self.vertices[i1], self.vertices[i2], self.epsilon)

  def _initialize_datastructures(self):
    """Initializes vertex queue and line properties from input lines.

    This method populates the vertex_queue with initial points from lines
    and pre-computes line properties like angles and distances.
    """
    for line_index, line in enumerate(self.lines):
      point1, point2 = line[0], line[1]
      if _compare_points(point1, point2, self.epsilon) > 0:
        point1, point2 = point2, point1

      new_vertex_index = len(self.vertices)
      self.vertices.append(point1)
      self.vertex_lines.append([])
      vertex1_index = self.vertex_queue.insert(new_vertex_index)
      if vertex1_index is None:
        vertex1_index = new_vertex_index
      else:
        self.vertices.pop()
        self.vertex_lines.pop()

      new_vertex_index = len(self.vertices)
      self.vertices.append(point2)
      self.vertex_lines.append([])
      vertex2_index = self.vertex_queue.insert(new_vertex_index)
      if vertex2_index is None:
        vertex2_index = new_vertex_index
      else:
        self.vertices.pop()
        self.vertex_lines.pop()

      self.line_vertices.append([vertex1_index, vertex2_index])
      diff_vector = math_utils.subtract(
          self.vertices[vertex2_index], self.vertices[vertex1_index]
      )
      unit_vector = math_utils.unit_vector(diff_vector)
      self.line_unit_vectors.append(unit_vector)
      self.line_angles.append(
          0 if diff_vector[1] < self.epsilon else math_utils.angle(diff_vector)
      )
      self.line_distances.append(
          math_utils.dot_product(
              math_utils.perpendicular_vector(unit_vector),
              self.vertices[vertex2_index],
          )
      )
      self.vertex_lines[vertex1_index].append(line_index)
    self.vertex_to_intersection_point_map = [None] * len(self.vertices)

  def _point_segment_dist(self, vertex_index: int, segment_index: int) -> float:
    """Calculates distance from point to segment's line.

    Args:
      vertex_index: Index of the vertex.
      segment_index: Index of the segment.

    Returns:
      The distance from the vertex to the line containing the segment.
    """
    return self.segment_distances[segment_index] - math_utils.dot_product(  # pyrefly: ignore[unsupported-operation]
        math_utils.perpendicular_vector(
            self.segment_unit_vectors[segment_index]
        ),
        self.vertices[vertex_index],
    )

  def _is_on_line(self, vertex_index: int, segment_index: int) -> bool:
    """Checks if point lies on segment's line within epsilon.

    Args:
      vertex_index: Index of the vertex.
      segment_index: Index of the segment.

    Returns:
      True if the vertex is on the line containing the segment.
    """
    return (
        abs(self._point_segment_dist(vertex_index, segment_index))
        < self.epsilon
    )

  def _compare_segments(self, segment1_index: int, segment2_index: int) -> int:
    """Compares segments to determine their relative order in the sweep line status.

    Segments are compared with respect to
    `self.vertices[self.current_vertex_index_for_sweep]`. If both segments
    pass through this vertex, they are ordered by angle, otherwise by distance.

    Args:
      segment1_index: Index of the first segment.
      segment2_index: Index of the second segment.

    Returns:
      -1, 0, or 1 based on segment order on the sweep line.
    """
    if not self._is_on_line(
        self.current_vertex_index_for_sweep, segment1_index
    ):
      raise ValueError("Error in sweep line sort")
    distance2 = self._point_segment_dist(
        self.current_vertex_index_for_sweep, segment2_index
    )
    if abs(distance2) < self.epsilon:
      endpoint1_index = self.segment_endpoints[segment1_index][1]
      if endpoint1_index is not None and self._is_on_line(
          endpoint1_index, segment2_index
      ):
        return 0
      if (
          self.segment_angles[segment2_index]
          - self.segment_angles[segment1_index]
          > 0
      ):
        return 1
      else:
        return -1
    return 1 if (-distance2 > 0) else -1

  def _get_segments_at_vertex(self, vertex_index: int) -> list[int]:
    """Gets segments passing through vertex_index and removes them from sweep line.

    Args:
      vertex_index: Index of the vertex to check.

    Returns:
      A list of segment indices that pass through the vertex.
    """
    segments_at_vertex: list[int] = []
    self.segment_endpoints[0][0] = vertex_index
    self.segment_distances[0] = math_utils.dot_product(
        math_utils.perpendicular_vector(self.segment_unit_vectors[0]),
        self.vertices[vertex_index],
    )
    prev_segment_index = self.sweep_line.prev(0)
    if (
        prev_segment_index is not None
        and self.segment_angles[prev_segment_index] == 0
    ):
      removed = self.sweep_line.remove_prev(0)
      if removed is not None:
        segments_at_vertex.append(removed)
    while True:
      next_segment_index = self.sweep_line.next(0)
      if next_segment_index is None or not self._is_on_line(
          vertex_index, next_segment_index
      ):
        break
      removed = self.sweep_line.remove_next(0)
      if removed is not None:
        segments_at_vertex.append(removed)
    return segments_at_vertex

  def _add_intersection_to_queue(
      self, intersection: Point | None, vertex: Point
  ):
    """Adds a new intersection point to the vertex queue if valid.

    Args:
      intersection: The intersection point, or None if no intersection.
      vertex: The current vertex being processed.
    """
    if (
        intersection is None
        or _compare_points(intersection, vertex, self.epsilon) == 0
        or (
            _compare_points(intersection, vertex, self.epsilon) < 0
            and intersection[1] <= vertex[1]
        )
    ):
      return
    new_intersection_vertex_index = len(self.vertices)
    self.vertices.append(intersection)
    self.vertex_lines.append([])
    self.vertex_to_intersection_point_map.append(None)
    inserted_index = self.vertex_queue.insert(new_intersection_vertex_index)
    if inserted_index is not None:
      self.vertices.pop()
      self.vertex_lines.pop()
      self.vertex_to_intersection_point_map.pop()

  def _find_and_add_intersections(self, vertex: Point):
    """Checks for intersections between neighbors on sweep line and adds to queue.

    Args:
      vertex: The current vertex being processed.
    """
    pairs = [
        [self.sweep_line.prev(0), self.sweep_line.next(0)],
    ]
    self.segment_angles[0] = float("-inf")
    pairs.append([self.sweep_line.prev(0), self.sweep_line.next(0)])
    self.segment_angles[0] = float("inf")

    for left_i, right_i in pairs:
      if left_i is None or right_i is None:
        continue
      p1_idx = self.segment_endpoints[left_i][0]
      p2_idx = self.segment_endpoints[right_i][0]
      intersection = _line_intersect(
          self.vertices[p1_idx],  # pyrefly: ignore[bad-index]
          math_utils.add(
              self.vertices[p1_idx], self.segment_unit_vectors[left_i]  # pyrefly: ignore[bad-index]
          ),
          self.vertices[p2_idx],  # pyrefly: ignore[bad-index]
          math_utils.add(
              self.vertices[p2_idx], self.segment_unit_vectors[right_i]  # pyrefly: ignore[bad-index]
          ),
          self.epsilon,
      )
      self._add_intersection_to_queue(intersection, vertex)

  def _insert_new_segments_on_sweep_line(self, vertex_index: int):
    """Inserts new segments starting at vertex_index onto sweep line.

    Args:
      vertex_index: Index of the vertex where new segments start.
    """
    self.vertex_lines[vertex_index].sort(
        key=lambda i: math_utils.distance_squared(
            self.vertices[vertex_index], self.vertices[self.line_vertices[i][1]]
        )
    )
    for line_index in self.vertex_lines[vertex_index]:
      segment_index = len(self.segment_endpoints)
      self.segment_endpoints.append(
          [vertex_index, self.line_vertices[line_index][1]]
      )
      self.segment_unit_vectors.append(self.line_unit_vectors[line_index])
      self.segment_angles.append(self.line_angles[line_index])
      self.segment_distances.append(self.line_distances[line_index])
      self.segment_lines.append([line_index])
      existing_i = self.sweep_line.insert(segment_index)
      if existing_i is not None:  # segment exists
        self.segment_endpoints.pop()
        self.segment_unit_vectors.pop()
        self.segment_angles.pop()
        self.segment_distances.pop()
        self.segment_lines.pop()
        self.segment_lines[existing_i].append(line_index)
      else:
        self.segment_endpoints[segment_index][1] = None

  def _build_final_edges(self) -> tuple[list[Edge], list[list[int]]]:
    """Builds final edge list from segments.

    Returns:
      A tuple containing edge_vertices and edge_lines.
    """
    output_edges = []
    output_edges_map = {}
    for segment_index in range(1, len(self.segment_endpoints)):
      point_pair_indices_or_none = [
          self.vertex_to_intersection_point_map[vertex_index]
          for vertex_index in self.segment_endpoints[segment_index]
          if vertex_index is not None
      ]
      if len(point_pair_indices_or_none) != 2:
        raise ValueError("Missing Endpoint")
      p1 = point_pair_indices_or_none[0]
      p2 = point_pair_indices_or_none[1]
      if p1 is None or p2 is None:
        raise ValueError("Missing Endpoint")
      point_pair_indices: list[int] = [p1, p2]
      if point_pair_indices[1] < point_pair_indices[0]:
        point_pair_indices.reverse()

      key = math_utils.list_to_tuple(point_pair_indices)
      edge_index = output_edges_map.get(key)
      if edge_index is None:
        edge_index = len(output_edges)
        output_edges.append([point_pair_indices, []])
        output_edges_map[key] = edge_index
      output_edges[edge_index][1].extend(self.segment_lines[segment_index])

    output_edges.sort(key=lambda x: (x[0][0], x[0][1]))
    result_edge_vertices = [x[0] for x in output_edges]
    result_edge_lines = [sorted(list(set(x[1]))) for x in output_edges]
    return result_edge_vertices, result_edge_lines

  def run(self) -> tuple[list[Point], list[Edge], list[list[int]]]:
    """Runs sweep-line algorithm.

    Returns:
        A tuple containing intersection_points, result_edge_vertices,
        and result_edge_lines.
    """
    self._initialize_datastructures()
    while self.vertex_queue.length > 0:
      timeout_lib.maybe_timeout_cooperatively()
      vertex_index = self.vertex_queue.remove_next(0)
      if vertex_index is None:
        raise ValueError("vertex_index should not be None")

      self.current_vertex_index_for_sweep = vertex_index
      vertex = self.vertices[vertex_index]
      segments_at_vertex = self._get_segments_at_vertex(vertex_index)

      # simplified vertex if no lines start/end here and <2 segments meet
      if not self.vertex_lines[vertex_index] and len(segments_at_vertex) < 2:
        if not segments_at_vertex:
          continue
        segment_index = segments_at_vertex[0]
        is_endpoint = any(
            _compare_points(
                self.vertices[self.line_vertices[i][1]], vertex, self.epsilon
            )
            <= 0
            for i in self.segment_lines[segment_index]
        )
        if not is_endpoint:
          self.sweep_line.insert(segment_index)
        continue

      # if only one segment meets vertex, and all lines from vertex are
      # parallel, merge lines into segment
      if len(segments_at_vertex) == 1:
        seg0 = segments_at_vertex[0]
        if all(
            self._is_on_line(self.line_vertices[i][1], seg0)
            for i in self.vertex_lines[vertex_index]
        ):
          self.sweep_line.insert(seg0)
          self.segment_lines[seg0].extend(self.vertex_lines[vertex_index])
          continue

      # It's an intersection point.
      self.vertex_to_intersection_point_map[vertex_index] = len(
          self.intersection_points
      )
      self.intersection_points.append(vertex)

      for seg_i in segments_at_vertex:
        timeout_lib.maybe_timeout_cooperatively()
        self.segment_endpoints[seg_i][1] = vertex_index
        for line_i in self.segment_lines[seg_i]:
          if (
              _compare_points(
                  self.vertices[self.line_vertices[line_i][1]],
                  vertex,
                  self.epsilon,
              )
              > 0
          ):
            self.vertex_lines[vertex_index].append(line_i)

      self._insert_new_segments_on_sweep_line(vertex_index)
      self._find_and_add_intersections(vertex)

    result_edge_vertices, result_edge_lines = self._build_final_edges()
    return self.intersection_points, result_edge_vertices, result_edge_lines


def _create_graph_from_lines_eps(
    lines: list[Line], epsilon: float
) -> tuple[list[Point], list[Edge], list[list[int]]]:
  """Creates a graph from lines using a given epsilon.

  This method implements a sweep-line algorithm to find all intersection
  points between lines, and builds a graph representation consisting of
  vertices at endpoints and intersection points, and edges representing
  segments of input lines between vertices.

  Args:
    lines: A list of lines, where each line is a tuple of two points.
    epsilon: Tolerance for floating-point comparisons.

  Returns:
    A tuple containing:
    - vertices: List of vertex coordinates of intersection points.
    - edge_vertices: List of edges defined by vertex indices.
    - edge_lines: List mapping edges to original line indices.
  """
  return _SweepLineRunner(lines, epsilon).run()
